 * @name scwin.goSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param idx
 * @returns
 * @hidden N
*/
scwin.goSearch = async function (idx) {
    /* sdd-asis-lifecycle:begin goSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const items = $("input[name=ch]:checked").map(function() {
            return $(this).val();
    }).get();
    $c.util.getComponent('ipt_ckKey').setValue(items);
    if (idx === '1') {
        $c.util.getComponent('ipt_pageIndex').setValue("1");
    }
    const fm = (document.JLDINF25700 || { elements: [] });
    fm.action = "/down/downList.do?method=drDownList";
    fm.target = "_self";
    await scwin.tx_goSearch();
    /* sdd-asis-lifecycle:end */
};


